    /// <summary>Get the properties associated with a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetWindowProperties</c>.</para>
    /// <para>The following read-only properties are provided by SDL:</para>
    /// <list type="bullet">
    /// <item>
    /// <description><c>SDL_PROP_WINDOW_SHAPE_POINTER</c>: the surface associated with a shaped window</description>
    /// </item>
    /// <item>
    /// <description><c>SDL_PROP_WINDOW_HDR_ENABLED_BOOLEAN</c>: true if the window has HDR headroom above the SDR white
